    data = _effective_test_data(config_test_data, scenario_case)
    slug = _safe_get_slug(data)
    if not slug:
        pytest.skip("Required test data 'project-slug' not provided in config.yml or scenario JSON")

    # Request validation (no body schema available; just ensure required param presence)
