    if isinstance(expected_status, str) and expected_status.isdigit():
        expected_status = int(expected_status)
    elif not isinstance(expected_status, int):
        # Default to 200 if not provided in scenario
        expected_status = 200

    assert resp.status_code == expected_status, f"Unexpected status for {endpoint}"

    # Response schema validation against 200 block
